python - <<'PY'
import urllib.parse, urllib.request, json
qs=['generative semantic IDs recommendation hyperbolic','hyperbolic recommendation next item sequential recommendation','generative semantic id sequential recommendation']
for q in qs:
 u='https://api.openalex.org/works?search='+urllib.parse.quote(q)+'&per-page=10&select=title,doi,publication_year,ids,open_access,biblio'
 try:
  d=json.load(urllib.request.urlopen(u,timeout=20))
  print('\nQUERY',q)
  for x in d['results']:
   print(x.get('title'), x.get('doi'), x.get('ids',{}).get('openalex'), x.get('open_access',{}).get('oa_url'))
 except Exception as e: print('ERR',e)
PY

